.workspace-full {
  min-height: 100dvh;
  width: 100%;
}
.workspace-full .workspace-sidebar {
  position: sticky;
  top: 0;
  height: 100dvh;
  min-height: 620px;
}
.workspace-full .workspace-body {
  min-width: 0;
  flex: 1;
}
.workspace-full .workspace-main {
  width: min(100%, 1480px);
  margin-inline: auto;
}
.workspace-full .workspace-title {
  align-items: flex-end;
}
.workspace-full .market-summaries {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.workspace-full .workspace-grid {
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, .85fr);
}
.workspace-full button,
.workspace-full input,
.workspace-full textarea {
  font: inherit;
}
.workspace-full button:focus-visible,
.workspace-full a:focus-visible,
.workspace-full input:focus-visible,
.workspace-full textarea:focus-visible {
  outline: 2px solid #789b5c;
  outline-offset: 3px;
}
@media (max-width: 1050px) {
  .workspace-full .workspace-sidebar {
    width: 150px;
    padding-inline: 10px;
  }
  .workspace-full .workspace-main {
    padding-inline: 22px;
  }
  .workspace-full .workspace-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .workspace-full .ai-panel .assistant-content {
    max-width: none;
  }
}
@media (max-width: 720px) {
  .workspace-full {
    display: block;
  }
  .workspace-full .workspace-sidebar {
    position: relative;
    width: 100%;
    height: auto;
    min-height: 0;
    padding: 12px 14px 10px;
    border-right: 0;
    border-bottom: 1px solid #e8ede3;
  }
  .workspace-full .workspace-sidebar > .brand {
    margin: 0 4px 12px;
  }
  .workspace-full .sidebar-caption,
  .workspace-full .sidebar-bottom,
  .workspace-full .workspace-sidebar nav .tiny-ai {
    display: none;
  }
  .workspace-full .workspace-sidebar nav {
    flex-direction: row;
    gap: 5px;
    overflow-x: auto;
    padding-bottom: 2px;
  }
  .workspace-full .workspace-sidebar nav button {
    flex: 0 0 auto;
    padding: 9px 10px;
    white-space: nowrap;
  }
  .workspace-full .workspace-sidebar nav button span {
    display: inline;
  }
  .workspace-full .workspace-body {
    width: 100%;
  }
  .workspace-full .workspace-topbar {
    padding: 13px 16px;
  }
  .workspace-full .workspace-main {
    padding: 22px 14px 30px;
  }
  .workspace-full .workspace-title {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
  .workspace-full .workspace-title h2 {
    font-size: clamp(22px, 6vw, 30px);
  }
  .workspace-full .market-summaries {
    grid-template-columns: 1fr;
  }
  .workspace-full .workspace-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .workspace-full .panel-heading {
    flex-wrap: wrap;
    gap: 12px;
  }
  .workspace-full .search-field {
    width: 100%;
  }
  .workspace-full .table-header,
  .workspace-full .market-row {
    grid-template-columns: minmax(105px, 1.4fr) minmax(75px, .8fr) minmax(65px, .7fr) 32px;
    gap: 8px;
  }
  .workspace-full .table-trend {
    display: none;
  }
  .workspace-full .table-header .table-trend {
    display: none;
  }
  .workspace-full .chart-panel,
  .workspace-full .ai-panel,
  .workspace-full .markets-panel,
  .workspace-full .tool-panel {
    padding: 16px;
  }
}
@media (max-width: 390px) {
  .workspace-full .workspace-topbar > div .data-badge {
    display: none;
  }
  .workspace-full .workspace-sidebar nav button {
    gap: 6px;
    padding: 8px;
    font-size: 8px;
  }
  .workspace-full .market-row {
    font-size: 9px;
