.workspace-full {
  --tw-glass-border: rgba(255,255,255,.78);
  --tw-glass-bg: rgba(255,255,255,.64);
  --tw-glass-shadow: 0 18px 55px rgba(52,55,92,.075), inset 0 1px 0 rgba(255,255,255,.92);
  min-height: 100dvh;
  background:
    radial-gradient(ellipse at 8% 5%, rgba(224,207,255,.48), transparent 36%),
    radial-gradient(ellipse at 96% 12%, rgba(190,245,237,.52), transparent 38%),
    linear-gradient(135deg,#f7f5ff 0%,#f4f6fc 48%,#effbf8 100%);
  color: #17182a;
}
.workspace-full .workspace-sidebar {
  z-index: 30;
  width: 258px;
  min-width: 258px;
  height: 100dvh;
  min-height: 100dvh;
  position: sticky;
  top: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 24px 15px 18px;
  border-right: 1px solid rgba(255,255,255,.88);
  background: linear-gradient(160deg,rgba(255,255,255,.82),rgba(255,255,255,.53));
  box-shadow: 10px 0 42px rgba(68,61,112,.055), inset -1px 0 rgba(255,255,255,.8);
  backdrop-filter: blur(28px) saturate(165%);
  -webkit-backdrop-filter: blur(28px) saturate(165%);
  scrollbar-width: thin;
  scrollbar-color: rgba(133,112,190,.22) transparent;
}
.workspace-full .sidebar-brand-row { display:flex; align-items:center; justify-content:space-between; margin:0 7px 28px; }
.workspace-full .workspace-sidebar > .sidebar-brand-row .brand { margin:0; }
.workspace-full .workspace-sidebar .brand-icon { width:34px;height:34px;border-radius:11px;box-shadow:0 7px 18px rgba(105,79,235,.22); }
.workspace-full .workspace-sidebar .brand-name { font-size:15px; }
.workspace-full .sidebar-caption { display:block; margin:0 11px 10px; color:#9a96ad; font-size:9px; font-weight:800; letter-spacing:.15em; }
.workspace-full .workspace-sidebar nav { display:flex; flex-direction:column; gap:3px; }
.workspace-full .sidebar-nav-item { display:block; }
.workspace-full .sidebar-group-label { display:block; padding:17px 11px 7px; color:#aaa6b9; font-size:8px; font-weight:800; letter-spacing:.13em; }
.workspace-full .workspace-sidebar nav button { width:100%; min-height:41px; display:flex; align-items:center; gap:11px; padding:9px 11px; border:1px solid transparent; border-radius:12px; color:#74758a; background:transparent; font-size:11px; font-weight:600; text-align:left; transition:all .18s ease; }
.workspace-full .workspace-sidebar nav button svg { width:17px;height:17px;color:#9693ad;flex:0 0 auto; }
.workspace-full .workspace-sidebar nav button:hover { color:#5946ad; background:rgba(255,255,255,.68); border-color:rgba(255,255,255,.9); box-shadow:0 5px 16px rgba(65,55,112,.055); transform:translateX(2px); }
.workspace-full .workspace-sidebar nav button.active { color:#5d43c7; background:linear-gradient(110deg,rgba(239,232,255,.96),rgba(230,240,255,.78)); border-color:rgba(255,255,255,.98); box-shadow:0 7px 20px rgba(105,82,184,.11),inset 0 1px rgba(255,255,255,.9); }
.workspace-full .workspace-sidebar nav button.active svg { color:#7759df; }
.workspace-full .workspace-sidebar nav .tiny-ai { margin-left:auto; color:#7255d7; background:rgba(255,255,255,.8); border:1px solid rgba(255,255,255,.95); border-radius:6px; padding:3px 6px; font-size:8px!important; }
.workspace-full .sidebar-bottom { margin-top:26px; padding-top:18px; border-top:1px solid rgba(139,130,171,.12); }
.workspace-full .demo-label { font-size:8px; color:#9b97aa; margin-bottom:12px; }
.workspace-full .sidebar-bottom > button { font-size:10px; color:#77768a; padding:10px; }
.workspace-full .profile { margin-top:14px; padding:14px 8px 2px; border-top:1px solid rgba(139,130,171,.12); }
.workspace-full .avatar { width:32px;height:32px; background:linear-gradient(145deg,#e9ddff,#d9f4f0); border:1px solid rgba(255,255,255,.95); color:#6b51c9; font-weight:800; }
.workspace-full .profile strong { font-size:10px; color:#35344b; }
.workspace-full .profile small { font-size:8px; color:#9390a3; }
.workspace-full .workspace-body { min-width:0; }
.workspace-full .workspace-topbar { position:sticky; top:0; z-index:20; height:72px; padding:0 clamp(22px,3vw,48px); background:rgba(255,255,255,.56); border-bottom:1px solid rgba(255,255,255,.82); backdrop-filter:blur(24px) saturate(160%); -webkit-backdrop-filter:blur(24px) saturate(160%); color:#53536b; font-size:12px; }
.workspace-full .workspace-topbar .muted { color:#9996aa; }
.workspace-full .workspace-topbar .breadcrumb { color:#c2bfd0; }
.workspace-full .workspace-topbar > div { gap:16px; }
.workspace-full .data-badge { font-size:9px; color:#8c8ba0; }
.workspace-full .data-badge > span { width:7px;height:7px; box-shadow:0 0 0 4px rgba(92,190,143,.12); }
.workspace-full .workspace-main { width:min(100%,1600px); padding:38px clamp(22px,3vw,48px) 48px; }
.workspace-full .workspace-greeting { color:#8c70dc; font-size:9px; font-weight:800; letter-spacing:.16em; }
.workspace-full .workspace-title { margin-bottom:28px; }
.workspace-full .workspace-title h2 { font-size:clamp(27px,3vw,39px); font-weight:700; letter-spacing:-.055em; color:#191a2d; }
