  margin-inline:0;
}
.workspace-full .workspace-sidebar.is-collapsed .sidebar-brand-row .brand {
  display:flex !important;
  width:100%;
  justify-content:center;
}
.workspace-full .workspace-sidebar.is-collapsed .sidebar-brand-row .brand-icon {
  display:grid !important;
  visibility:visible !important;
  opacity:1 !important;
  width:40px;height:40px;flex:0 0 40px;
}
.workspace-full .workspace-sidebar.is-collapsed .sidebar-brand-row .brand > span:not(.brand-icon) {
  display:none !important;
}
.workspace-full .workspace-sidebar.is-collapsed > .sidebar-caption { display:none; }
.workspace-full .workspace-sidebar.is-collapsed > nav {
  margin-top:12px;
}
.workspace-full .workspace-sidebar.is-collapsed > .sidebar-bottom {
  padding-top:12px;
}
.workspace-full .workspace-sidebar.is-collapsed .profile {
  display:flex;
  justify-content:center;
  padding:8px 4px;
}
.workspace-full .workspace-sidebar.is-collapsed .profile .avatar {
  display:grid;
}
.workspace-full .workspace-sidebar.is-collapsed .profile > div,
.workspace-full .workspace-sidebar.is-collapsed .profile > svg {
  display:none !important;
}
/* Taller, more legible fixed top bar */
.workspace-full .workspace-topbar {
  height:82px !important;
  flex-basis:82px !important;
  min-height:82px;
  padding-inline:34px !important;
}
.workspace-full .workspace-topbar-left,
.workspace-full .workspace-topbar-actions {
  min-height:100%;
  align-items:center;
}
.workspace-full .sidebar-toggle,
.workspace-full .topbar-icon-action {
  width:44px;height:44px;
}
.workspace-full .topbar-profile-action {
  min-height:48px;
}
@media(max-width:720px) {
  .workspace-full .workspace-sidebar {
    height:100dvh !important;
    overflow:hidden !important;
  }
  .workspace-full .workspace-sidebar > nav {
    overflow-y:auto;
    flex:1 1 auto;
  }
  .workspace-full .workspace-sidebar > .sidebar-bottom {
    padding-bottom:calc(8px + env(safe-area-inset-bottom));
  }
  .workspace-full .workspace-topbar {
    height:68px !important;
    flex-basis:68px !important;
    min-height:68px;
    padding-inline:14px !important;
  }
}


/* Main workspace: one clear right-edge scroll area */
.workspace-full .workspace-body {
  flex:1 1 auto;
  min-width:0;
  width:auto;
  height:100vh;
  min-height:0;
  display:flex;
  flex-direction:column;
  overflow:hidden;
}
.workspace-full .workspace-main {
  flex:1 1 auto;
  min-height:0;
  min-width:0;
  width:100%;
  overflow-y:auto !important;
  overflow-x:hidden;
  overscroll-behavior-y:contain;
  scrollbar-gutter:stable;
  padding:32px clamp(22px,3vw,46px) 48px;
  scroll-behavior:smooth;
  scrollbar-width:thin;
  scrollbar-color:rgba(119,99,197,.62) rgba(255,255,255,.22);
}
.workspace-full .workspace-main::-webkit-scrollbar { width:11px; }
.workspace-full .workspace-main::-webkit-scrollbar-track {
  background:rgba(255,255,255,.24);
  border-left:1px solid rgba(255,255,255,.38);
}
.workspace-full .workspace-main::-webkit-scrollbar-thumb {
  min-height:64px;
  border:3px solid transparent;
  border-radius:20px;
  background:linear-gradient(180deg,rgba(145,111,229,.78),rgba(73,177,174,.72)) padding-box;
}
.workspace-full .workspace-main::-webkit-scrollbar-thumb:hover {
  background:linear-gradient(180deg,rgba(126,91,220,.92),rgba(48,157,157,.9)) padding-box;
}
/* Prevent the sticky page heading from visually washing out the cards */
.workspace-full .workspace-title {
  position:relative;
  top:auto;
  z-index:2;
  margin:0 0 22px;
  padding:20px 22px;
  border:1px solid rgba(255,255,255,.9);
  border-radius:20px;
  background:linear-gradient(110deg,rgba(250,247,255,.88),rgba(247,253,252,.86));
  box-shadow:0 10px 28px rgba(63,57,104,.045);
  backdrop-filter:blur(22px) saturate(155%);
  -webkit-backdrop-filter:blur(22px) saturate(155%);
}
/* Consistent Apple-inspired translucent glass on all dashboard surfaces */
.workspace-full .summary-card,
.workspace-full .panel,
.workspace-full .overview-module-card,
.workspace-full .module-placeholder,
.workspace-full .market-table,
.workspace-full .overview-feed-item {
  background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(255,255,255,.48)) !important;
  border:1px solid rgba(255,255,255,.88) !important;
  box-shadow:
    0 14px 38px rgba(48,52,91,.055),
    inset 0 1px 0 rgba(255,255,255,.88);
  backdrop-filter:blur(24px) saturate(165%);
  -webkit-backdrop-filter:blur(24px) saturate(165%);
}
.workspace-full .summary-card {
  border-radius:20px;
  transition:transform .2s ease,box-shadow .2s ease,background .2s ease;
}
.workspace-full .summary-card:hover,
.workspace-full .summary-card.chosen {
  transform:translateY(-2px);
  background:linear-gradient(145deg,rgba(255,255,255,.92),rgba(248,246,255,.72)) !important;
  box-shadow:0 18px 42px rgba(81,70,145,.10),inset 0 1px rgba(255,255,255,.95);
}
.workspace-full .panel {
  border-radius:22px;
  overflow:hidden;
}
.workspace-full .panel-heading {
  background:rgba(255,255,255,.20);
  border-bottom:1px solid rgba(255,255,255,.48);
}
.workspace-full .overview-module-card {
  border-radius:16px;
  transition:transform .2s ease,box-shadow .2s ease;
}
.workspace-full .overview-module-card:hover {
  transform:translateY(-2px);
  box-shadow:0 15px 35px rgba(68,61,120,.10),inset 0 1px rgba(255,255,255,.9);
}
.workspace-full .market-table {
  border-radius:18px;
  overflow:hidden;
}
.workspace-full .market-table .table-header,
.workspace-full .market-table > div {
  background:rgba(255,255,255,.18);
  border-color:rgba(255,255,255,.55);
}
.workspace-full .overview-feed-item {
  border-radius:0;
  border-left:0 !important;
  border-right:0 !important;
  border-top:0 !important;
  border-bottom:1px solid rgba(255,255,255,.55) !important;
}
.workspace-full .overview-feed-item:hover {
  background:rgba(255,255,255,.78) !important;
}
.workspace-full .floating-ai-window {
  background:rgba(255,255,255,.84);
  border:1px solid rgba(255,255,255,.94);
  box-shadow:0 24px 70px rgba(48,43,91,.18),inset 0 1px rgba(255,255,255,.95);
  backdrop-filter:blur(28px) saturate(175%);
  -webkit-backdrop-filter:blur(28px) saturate(175%);
}
@media(max-width:720px) {
  .workspace-full .workspace-body {
    height:auto;
    min-height:100dvh;
    overflow:visible;
    display:block;
  }
  .workspace-full .workspace-main {
    min-height:calc(100dvh - 68px);
    overflow:visible !important;
    padding:22px 14px 36px;
    scrollbar-gutter:auto;
  }
  .workspace-full .workspace-title {
    padding:16px;
    margin-bottom:16px;
  }
}


