.passport-page { display:grid; gap:22px; }
.passport-hero {
  position:relative; overflow:hidden; padding:30px 34px;
  min-height:245px;
  background:
    radial-gradient(ellipse at 88% 10%,rgba(116,226,210,.26),transparent 42%),
    radial-gradient(ellipse at 12% 90%,rgba(154,119,255,.23),transparent 48%),
    linear-gradient(125deg,rgba(255,255,255,.88),rgba(247,246,255,.62)) !important;
  border:1px solid rgba(255,255,255,.92) !important;
  box-shadow:0 20px 55px rgba(63,54,113,.08),inset 0 1px rgba(255,255,255,.95);
  backdrop-filter:blur(28px) saturate(170%);
  -webkit-backdrop-filter:blur(28px) saturate(170%);
}
.passport-hero-top,.passport-number-row,.passport-section-heading,.passport-form-actions {
  display:flex;align-items:center;justify-content:space-between;gap:16px;
}
.passport-mark,.passport-info-icon {
  display:grid;place-items:center;width:48px;height:48px;border-radius:16px;
  color:#7959e8;background:linear-gradient(145deg,rgba(139,111,255,.16),rgba(69,192,183,.13));
  border:1px solid rgba(255,255,255,.85);
  box-shadow:0 8px 24px rgba(104,84,185,.10),inset 0 1px rgba(255,255,255,.9);
}
.passport-status {
  display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border-radius:99px;
  color:#477d68;background:rgba(230,248,238,.72);font-size:12px;font-weight:650;
  border:1px solid rgba(255,255,255,.8);
}
.passport-status > span { width:7px;height:7px;border-radius:50%;background:#4bb783; }
.passport-hero-content { margin:24px 0 20px; }
.passport-hero-content h3 { margin:5px 0 8px;font-size:clamp(27px,3vw,38px);letter-spacing:-.045em;color:#22233a; }
.passport-hero-content > p:last-child { margin:0;color:#777b94;font-size:14px; }
.passport-number-row { max-width:340px;padding-top:14px;border-top:1px solid rgba(137,126,183,.16); }
.passport-number-row div { display:grid;gap:5px; }
.passport-number-row small,.passport-info-card > small { color:#9293aa;font-size:9px;font-weight:750;letter-spacing:.14em; }
.passport-number-row strong { font-size:14px;letter-spacing:.09em;color:#36334e; }
.passport-number-row > svg { color:#8a72e9; }
.passport-section-heading { margin:4px 2px 0; }
.passport-section-heading h3 { margin:3px 0 0;font-size:22px;letter-spacing:-.035em; }
.passport-info-grid { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px; }
.passport-info-card {
  display:flex;flex-direction:column;align-items:flex-start;gap:9px;
  padding:19px 20px;min-height:155px;
  background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(255,255,255,.48)) !important;
  border:1px solid rgba(255,255,255,.9) !important;
  box-shadow:0 12px 32px rgba(53,52,93,.045),inset 0 1px rgba(255,255,255,.92);
  backdrop-filter:blur(22px) saturate(160%);-webkit-backdrop-filter:blur(22px) saturate(160%);
}
.passport-info-icon { width:36px;height:36px;border-radius:12px; }
.passport-info-card > strong { color:#292941;font-size:16px;overflow-wrap:anywhere; }
.passport-info-card > span:last-child { color:#9697aa;font-size:11px; }
.passport-lower-grid { display:grid;grid-template-columns:1fr 1fr;gap:16px; }
.passport-admin-card,.passport-security-card,.passport-edit-form {
  padding:21px 23px;
  background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(255,255,255,.48)) !important;
  border:1px solid rgba(255,255,255,.9) !important;
  box-shadow:0 12px 32px rgba(53,52,93,.045),inset 0 1px rgba(255,255,255,.92);
  backdrop-filter:blur(22px) saturate(160%);-webkit-backdrop-filter:blur(22px) saturate(160%);
}
.passport-detail-row { display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid rgba(133,126,169,.13);font-size:13px; }
.passport-detail-row > span,.passport-security-card > p { color:#85869d; }
.passport-detail-row > strong { color:#33334b;text-align:right; }
.passport-active { color:#26966e !important; }
.passport-hint { color:#9091a6;font-size:11px;line-height:1.6;margin:13px 0; }
.passport-security-card > p { font-size:13px;line-height:1.7;margin:0 0 17px; }
.passport-edit-form { display:grid;gap:15px; }
.passport-form-grid { display:grid;grid-template-columns:1fr 1fr;gap:14px; }
.passport-form-grid label,.passport-password-form label { display:grid;gap:7px;color:#51516d;font-size:12px;font-weight:650; }
.passport-form-grid input,.passport-password-form input {
  width:100%;min-height:43px;padding:10px 12px;border:1px solid rgba(145,139,177,.2);
  border-radius:12px;background:rgba(255,255,255,.68);color:#292941;outline:none;
}
.passport-form-grid input:focus,.passport-password-form input:focus {
  border-color:rgba(125,97,229,.58);box-shadow:0 0 0 3px rgba(125,97,229,.10);
}
.passport-password-form { display:grid;gap:12px;margin-top:15px; }
.passport-form-actions { justify-content:flex-end; }
.passport-success { display:flex;align-items:center;gap:8px;padding:11px 14px;border-radius:12px;background:rgba(226,247,236,.72);color:#277a59;font-size:13px; }
@media(max-width:900px) {
  .passport-info-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .passport-lower-grid { grid-template-columns:1fr; }
}
@media(max-width:600px) {
  .passport-hero { padding:22px 19px;min-height:225px; }
  .passport-section-heading { align-items:flex-start; }
