.workspace-full .assistant-chat-page {
  width:100%;
  max-width:none;
  min-height:calc(100vh - 150px);
  margin:0;
  padding:0;
  border-radius:24px;
  overflow:hidden;
  background:linear-gradient(145deg,rgba(255,255,255,.82),rgba(255,255,255,.58));
  border:1px solid rgba(255,255,255,.92);
  box-shadow:0 20px 55px rgba(54,48,103,.075),inset 0 1px 0 rgba(255,255,255,.95);
  backdrop-filter:blur(28px) saturate(170%);
  -webkit-backdrop-filter:blur(28px) saturate(170%);
}
.assistant-chat-page > .panel-heading { display:none; }
.assistant-chat-shell {
  min-height:calc(100vh - 152px);
  display:flex;
  flex-direction:column;
  padding:24px clamp(18px,3vw,38px) 18px;
  gap:18px;
}
.assistant-chat-header {
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding-bottom:17px;border-bottom:1px solid rgba(255,255,255,.9);
}
.assistant-chat-brand { display:flex;align-items:center;gap:12px; }
.assistant-chat-icon {
  width:44px;height:44px;border-radius:15px;display:grid;place-items:center;
  color:#795be9;background:linear-gradient(145deg,rgba(229,220,255,.9),rgba(215,246,239,.85));
  box-shadow:0 8px 22px rgba(108,83,197,.12),inset 0 1px rgba(255,255,255,.95);
}
.assistant-chat-brand strong { display:block;font-size:17px;letter-spacing:-.035em;color:#25243d; }
.assistant-chat-brand small { display:block;margin-top:4px;font-size:11px;color:#898aa1; }
.assistant-credit-pill {
  display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:999px;
  border:1px solid rgba(255,255,255,.95);background:rgba(255,255,255,.55);
  color:#85869a;font-size:10px;white-space:nowrap;
}
.assistant-credit-pill > span { width:7px;height:7px;border-radius:50%;background:#8dbb86; }
.assistant-filter-bar {
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;
  padding:14px;border:1px solid rgba(255,255,255,.9);border-radius:17px;
  background:rgba(255,255,255,.42);box-shadow:inset 0 1px rgba(255,255,255,.8);
}
.assistant-filter-bar label { display:flex;flex-direction:column;gap:7px;font-size:10px;font-weight:650;color:#77778f; }
.assistant-filter-bar select {
  width:100%;min-width:0;height:40px;padding:0 11px;border-radius:11px;
  border:1px solid rgba(221,220,239,.85);background:rgba(255,255,255,.78);
  color:#393850;font:inherit;font-size:11px;outline:none;
}
.assistant-filter-bar select:focus { border-color:#a99af0;box-shadow:0 0 0 3px rgba(137,104,235,.10); }
.assistant-chat-transcript {
  flex:1 1 auto;min-height:350px;max-height:calc(100vh - 500px);
  overflow-y:auto;padding:12px 5px 18px;scrollbar-width:thin;
  scrollbar-color:rgba(143,119,215,.45) transparent;
}
.assistant-welcome {
  max-width:620px;margin:20px auto 0;text-align:center;padding:20px;
}
.assistant-welcome .assistant-orb { width:54px;height:54px;margin:0 auto 22px; }
.assistant-welcome h3 { font-size:25px;letter-spacing:-.045em;color:#28263f; }
.assistant-welcome p { margin:9px auto 22px;max-width:460px;font-size:13px;line-height:1.7;color:#85869b; }
.assistant-starters { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px; }
.assistant-starters button {
  min-height:64px;display:flex;align-items:center;justify-content:space-between;gap:8px;
  text-align:left;padding:13px;border-radius:13px;
  border:1px solid rgba(224,222,242,.85);background:rgba(255,255,255,.64);
  color:#77758f;font-size:11px;line-height:1.5;transition:.18s ease;
}
.assistant-starters button:hover { background:rgba(255,255,255,.94);border-color:#c9bdf5;transform:translateY(-1px); }
.assistant-chat-transcript .messages { max-height:none;overflow:visible;display:flex;flex-direction:column;gap:13px; }
.assistant-chat-transcript .chat-message {
  max-width:min(820px,88%);display:flex;flex-direction:column;gap:7px;
  padding:15px 17px;border-radius:17px;font-size:13px;line-height:1.75;
  white-space:pre-wrap;color:#55566e;background:rgba(255,255,255,.75);
  border:1px solid rgba(255,255,255,.95);box-shadow:0 8px 22px rgba(51,49,91,.045);
}
.assistant-chat-transcript .chat-message.user {
  align-self:flex-end;margin:0 0 0 auto;color:#fff;
  background:linear-gradient(125deg,#8562ed,#536cf0);border:0;
  border-bottom-right-radius:5px;
}
.assistant-chat-transcript .chat-message.assistant {
  align-self:flex-start;border-bottom-left-radius:5px;
}
.assistant-chat-transcript .chat-role { font-size:10px;font-weight:750;opacity:.72; }
.assistant-chat-transcript .thinking { font-size:12px;padding:12px;color:#8882ae; }
.assistant-composer {
  flex:0 0 auto;padding:12px;border-radius:18px;
  border:1px solid rgba(255,255,255,.98);background:rgba(255,255,255,.82);
  box-shadow:0 12px 34px rgba(54,49,98,.07),inset 0 1px rgba(255,255,255,.98);
  backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px);
}
.assistant-composer-row { display:flex;align-items:flex-end;gap:10px; }
.assistant-attach-button {
  width:42px;height:42px;flex:0 0 42px;border-radius:13px;display:grid;place-items:center;
  color:#8066d9;background:rgba(237,232,255,.8);cursor:pointer;
}
.assistant-attach-button input { display:none; }
.assistant-composer-row textarea {
