html body .workspace.workspace-full .workspace-body > header.workspace-topbar .mobile-menu-trigger:hover svg,
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-icon-action:hover svg {
  color: #554238 !important;
  stroke: #554238 !important;
}

/* Profile chevron and avatar-adjacent icon use the same muted warm-grey family. */
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-profile-action > svg {
  width: 14px !important;
  height: 14px !important;
  color: #786f68 !important;
  stroke: #786f68 !important;
}
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-profile-action {
  gap: 9px !important;
}
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-profile-copy {
  gap: 2px !important;
}
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-profile-copy strong {
  color: #59463b !important;
  font-size: 12px !important;
}
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-profile-copy small {
  color: #88796e !important;
  font-size: 10px !important;
}

/* Keep notification dot and semantic status colors unchanged. */
html body .workspace.workspace-full .workspace-body > header.workspace-topbar .notification-dot {
  background: #d76b63 !important;
}

/* Compact action spacing on narrow screens; no structural changes. */
@media (max-width: 900px) {
  html body .workspace.workspace-full .workspace-body > header.workspace-topbar {
    gap: 8px !important;
  }
  html body .workspace.workspace-full .workspace-body > header.workspace-topbar .workspace-topbar-actions {
    gap: 8px !important;
  }
}
@media (max-width: 560px) {
  html body .workspace.workspace-full .workspace-body > header.workspace-topbar .topbar-context {
