/* Modular dashboard page boundaries and topbar section switcher */
.dashboard-module-page {
  display: contents;
}
.dashboard-page-switcher {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-width: 150px;
  max-width: min(260px, 42vw);
}
.dashboard-page-switcher select {
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 5px 25px 5px 9px;
  border: 1px solid rgba(130, 112, 180, .18);
  border-radius: 9px;
  color: var(--ink, #171727);
  background: rgba(255,255,255,.42);
  font: inherit;
  font-weight: 650;
  cursor: pointer;
  outline: none;
}
.dashboard-page-switcher select:focus-visible {
  outline: 2px solid #8b6be8;
  outline-offset: 2px;
}
.dashboard-page-switcher > svg {
  position: absolute;
  right: 8px;
  pointer-events: none;
  color: var(--muted, #777);
}
@media (max-width: 640px) {
  .dashboard-page-switcher {
    min-width: 110px;
    max-width: 48vw;
  }
  .dashboard-page-switcher select {
    font-size: 12px;
  }
}
